# Stops any local EventFeed server on port 3000 and deletes the local prototype database.
# The database is regenerated by: npm.cmd run dev, then npm.cmd run upload
$conns = Get-NetTCPConnection -LocalPort 3000 -State Listen -ErrorAction SilentlyContinue
foreach ($c in $conns) {
    Write-Host "Stopping process $($c.OwningProcess) on port 3000"
    Stop-Process -Id $c.OwningProcess -Force
}
Start-Sleep -Seconds 1; Write-Host 'Stopped'
Remove-Item data/eventfeed.db* -ErrorAction SilentlyContinue
Write-Host "Database removed: $(-not (Test-Path data/eventfeed.db))"
Write-Host 'DONE'
